const raw=$input.first().json?.data?.issues?.nodes||[];
const scored=raw.map(f=>{
  const age=Math.floor((Date.now()-new Date(f.createdAt))/86400000);
  const sla=f.severity==='CRITICAL'?3:f.severity==='HIGH'?7:30;
  return{finding_id:f.id,title:f.title,severity:f.severity,resource:f.resource?.name,
    resource_type:f.resource?.type,age_days:age,sla_days:sla,
    sla_breached:age>sla,created_at:f.createdAt};
});
scored.sort((a,b)=>b.sla_breached-a.sla_breached||b.age_days-a.age_days);
const breached=scored.filter(s=>s.sla_breached);
return[{json:{total:scored.length,sla_breached:breached.length,critical:scored.filter(s=>s.severity==='CRITICAL').length,
  findings:scored,breached_findings:breached,scanned_at:new Date().toISOString()}}];

